import {initialState,skills,transition,summary,mentorLoad} from './domain.js';
const key='aitu-mentorship-prototype-v1';
let state, storageWarning='';
try {state=JSON.parse(localStorage.getItem(key)||'null');if(state?.schema!==1)state=initialState();}catch{state=initialState();storageWarning='Локальное хранилище недоступно или повреждено. Сессия начата с демо-данных.';}
let page='dashboard',role='teacher',chosenSkill='',query='',area='Все',pairId='';
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const skillName=id=>skills.find(s=>s.id===id)?.name||id;
const names={teacher:'Преподаватель',mentor:'Наставник',mentee:'Наставляемый',director:'Директор Школы',rector:'Регистратор распоряжения',department:'Академический департамент'};
const statuses={review:'Проверка Школы',training:'Ожидается инструктаж',published:'Доступен',returned:'Возвращена',submitted:'Ожидает подбора',matching:'Пара предложена',consents:'Согласия сторон',presented:'Представление директора',planning:'Подготовка и утверждение плана',active:'Программа идет',completed:'Завершена',ended:'Прекращена'};
const input=(name,label,type='text',value='',required=true)=>`<label class="field">${esc(label)}${required?' *':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0"':''}></label>`;
const textarea=(name,label,value='',required=true)=>`<label class="field wide">${esc(label)}${required?' *':''}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const select=(name,label,options,value='',required=true)=>`<label class="field">${esc(label)}${required?' *':''}<select name="${name}" ${required?'required':''}>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const check=(name,label)=>`<label class="check"><input type="checkbox" name="${name}">${esc(label)}</label>`;
const hidden=(name,value)=>`<input type="hidden" name="${name}" value="${esc(value)}">`;
const btn=(action,id,text)=>`<button data-action="${action}" data-id="${esc(id)}">${esc(text)}</button>`;
const form=(action,body,id='',label='Сохранить')=>`<form data-action="${action}">${hidden('id',id)}<div class="formgrid">${body}</div><div class="formactions"><button class="primary" type="submit">${esc(label)}</button></div></form>`;
const detail=(title,body)=>`<details><summary>${esc(title)}</summary>${body}</details>`;
const date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'}):'—';
const formats=[['Очный','Очный'],['Дистанционный','Дистанционный'],['Смешанный','Смешанный']];
function notify(text,error=false){const n=document.querySelector('#notice');n.textContent=text;n.classList.toggle('error',error);n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',6000);}
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;}catch{throw new Error('Не удалось сохранить изменения. Проверьте доступность и объем хранилища браузера.');}}
function skillChecks(){return `<fieldset class="wide"><legend>Направления поддержки</legend>${skills.map(s=>`<label class="check"><input type="checkbox" name="skills" value="${s.id}" ${chosenSkill===s.id?'checked':''}>${esc(s.name)}</label>`).join('')}</fieldset>`;}
function dashboard(){const stats=summary(state);const selected=skills.find(s=>s.id===chosenSkill);const list=skills.filter(s=>(area==='Все'||s.area===area)&&`${s.name} ${s.description}`.toLowerCase().includes(query.toLowerCase()));return `
<section class="hero"><div><span class="eyebrow">Профессиональное развитие · AITU</span><h1>Расти в преподавании.<br>Вместе с коллегами.</h1><p class="lead">Найдите навык, который хотите развить, выберите наставника или начните с мероприятия.</p></div><aside class="hero-aside"><span class="eyebrow">Ваш маршрут</span><h3>От запроса к результату</h3><p>01 · Выберите направление</p><p>02 · Найдите поддержку</p><p>03 · Составьте совместный план</p><p>04 · Практикуйте и обсуждайте</p></aside></section>
<div class="stats">${[['Наставники',stats.published],['Профессиональные запросы',stats.requests],['Активные программы',stats.active],['Завершенные программы',stats.completed]].map(([l,n])=>`<div class="stat"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div>
<section><div class="sectionhead"><div><span class="eyebrow">Каталог направлений</span><h2>Какой навык вы хотите развить?</h2></div><label class="field search">Поиск навыка<input id="search" value="${esc(query)}" placeholder="Например, обратная связь"></label></div><p class="hint">Если запрос еще не сформулирован, начните с описания навыков.</p><div class="filters">${['Все',...new Set(skills.map(s=>s.area))].map(a=>`<button data-area="${esc(a)}" class="${area===a?'selected':''}">${esc(a)}</button>`).join('')}</div><div class="grid">${list.map((s,i)=>`<article class="card ${chosenSkill===s.id?'selected':''}"><span class="tag">${esc(s.area)}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="actions"><button data-skill="${s.id}" aria-pressed="${chosenSkill===s.id}">Изучить направление →</button></div></article>`).join('')||'<div class="empty">Навыки не найдены. Попробуйте другой запрос.</div>'}</div></section>
${selected?`<section class="panel" style="margin-top:24px"><div class="sectionhead"><h2>${esc(selected.name)}</h2><button data-skill="">Сбросить выбор</button></div><p>${esc(selected.description)}</p><div class="actions"><button class="primary" data-page="mentee-form">Запросить наставничество</button><button data-page="mentors">Посмотреть наставников</button></div></section>`:''}
<section><div class="sectionhead"><div><span class="eyebrow">Витрина мероприятий</span><h2>${selected?'События по выбранному навыку':'Учитесь через практику'}</h2></div><span class="hint">Демонстрационные мероприятия</span></div><div class="grid">${state.events.filter(e=>!chosenSkill||e.skills.includes(chosenSkill)).map(e=>`<article class="card"><span class="date">${date(e.date)} · ${esc(e.time)}</span><h3>${esc(e.title)}</h3><p>${esc(e.format)}</p><p class="hint">${esc(e.location)}</p><div>${e.skills.map(s=>`<span class="tag">${esc(skillName(s))}</span>`).join(' ')}</div><p class="hint">Свободно ${e.capacity-state.enrollments.filter(x=>x.eventId===e.id).length} мест</p>${detail('Записаться',form('event-enroll',input('name','Демо-имя участника'),e.id,'Записаться'))}</article>`).join('')||'<div class="empty">По этому навыку мероприятий пока нет. Можно подать запрос на наставничество.</div>'}</div></section>`;}
function mentorForm(){return `<span class="eyebrow">Стать наставником</span><h1>Поделитесь своей экспертизой</h1><p class="lead">Школа проверит карточку и критерии положения. Перед началом работы потребуется вводный инструктаж.</p><div class="note">Для демонстрации вводите только вымышленные сведения. Минимальный преподавательский стаж — 3 года.</div><section class="panel">${form('mentor-submit',input('name','Имя преподавателя')+input('school','Школа','text','Школа цифровых технологий')+input('experience','Стаж преподавания в вузе, лет','number')+input('qualification','Квалификация')+textarea('evidence','Подтвержденные результаты педагогической деятельности')+textarea('expertise','Области экспертизы и запросы, с которыми готовы помочь')+skillChecks()+input('formats','Возможные форматы взаимодействия')+input('availability','Доступность и периодичность')+`<div class="wide">${check('consent','Готов(а) регулярно взаимодействовать, соблюдать конфиденциальность и участвовать в программе')}</div>`,'','Отправить в Школу')}</section>`;}
function menteeForm(){return `<span class="eyebrow">Найти наставника</span><h1>С чего начнем ваше развитие?</h1><p class="lead">Опишите профессиональную потребность. Наставника можно выбрать сейчас или вместе со Школой.</p><div class="note">Здесь используются только демо-сведения. Частные затруднения не включаются в управленческую аналитику.</div><section class="panel">${form('request-submit',input('name','Имя преподавателя')+input('school','Школа','text','Школа цифровых технологий')+textarea('need','Индивидуальный профессиональный запрос')+textarea('goal','Ожидаемый результат')+skillChecks()+select('format','Предпочтительный формат',formats)+select('period','Период',[['Один триместр','Один триместр'],['Один учебный год','Один учебный год']])+select('mentorId','Предпочтительный наставник',[['','Помогите подобрать'],...state.mentors.filter(m=>m.status==='published').map(m=>[m.id,m.name])],'',false)+`<div class="wide">${check('consent','Согласен(на) участвовать в программе и соблюдать конфиденциальность')}</div>`,'','Подать запрос')}</section>`;}
function mentorCards(){return `<span class="eyebrow">Коллеги рядом</span><h1>Наставники и экспертиза</h1><p class="lead">Выберите поддержку по профессиональному запросу. Окончательное назначение проходит через Школу.</p><div class="sectionhead"><h2>${chosenSkill?esc(skillName(chosenSkill)):'Все направления'}</h2>${chosenSkill?'<button data-skill="">Показать всех</button>':''}</div><div class="grid">${state.mentors.filter(m=>m.status==='published'&&(!chosenSkill||m.skills.includes(chosenSkill))).map(m=>`<article class="card"><span class="tag">${esc(m.school)}</span><h3>${esc(m.name)}</h3><p>${esc(m.expertise)}</p><p class="hint">${m.experience} лет · ${esc(m.formats)}</p><div>${m.skills.map(s=>`<span class="tag">${esc(skillName(s))}</span>`).join(' ')}</div><p class="hint">Зарезервировано пар: ${mentorLoad(state,m.id)} · ${esc(m.availability)}</p><button data-mentor="${m.id}" class="primary">Запросить поддержку</button></article>`).join('')||'<div class="empty">По этому навыку пока нет опубликованных наставников. Подайте запрос без кандидатуры.</div>'}</div>`;}
function requestsPage(){return `<span class="eyebrow">Организация программы</span><h1>Заявки и согласование</h1><p class="lead">Школа проверяет кандидатов, согласует пару с обеими сторонами и представляет назначение.</p><h2 style="margin-top:28px">Карточки наставников</h2><div class="stack">${state.mentors.filter(m=>m.status!=='published').map(m=>`<article class="panel"><span class="step">${statuses[m.status]}</span><h3>${esc(m.name)}</h3><p>${esc(m.qualification)} · Стаж: ${esc(m.experience)} лет</p><p>${esc(m.evidence)}</p><p>${esc(m.expertise)} · ${esc(m.formats)} · ${esc(m.availability)}</p>${m.reason?`<p>Причина возврата: ${esc(m.reason)}</p>`:''}${role==='director'&&m.status==='review'?form('mentor-review',`<div class="wide">${check('verified','Проверены стаж, результаты, компетенции, процедуры AITU, коммуникация, готовность и опыт по запросу')}</div>`,m.id,'Подтвердить критерии'):''}${role==='department'&&m.status==='training'?form('mentor-training',input('date','Дата инструктажа','date'),m.id,'Подтвердить инструктаж'):''}${role==='director'&&['review','training'].includes(m.status)?detail('Вернуть карточку',form('mentor-return',textarea('reason','Причина возврата'),m.id,'Вернуть')):''}</article>`).join('')||'<div class="empty">Новых карточек нет. Подайте заявку через кнопку сверху.</div>'}</div><h2 style="margin-top:28px">Запросы наставляемых</h2><div class="stack">${state.requests.map(r=>`<article class="panel"><span class="step">${statuses[r.status]}</span><h3>${esc(r.name)}</h3><p>${esc(r.need)}</p><p class="hint">Цель: ${esc(r.goal)} · ${esc(r.period)} · ${esc(r.format)}</p><p class="hint">Навыки: ${(r.skills||[]).map(skillName).map(esc).join(', ')||'Нужна помощь с выбором'}</p>${role==='director'&&r.status==='submitted'?form('pair-propose',select('mentorId','Предложить наставника',state.mentors.filter(m=>m.status==='published').map(m=>[m.id,m.name]),r.mentorId),r.id,'Предложить пару'):''}</article>`).join('')||'<div class="empty">Запросов пока нет.</div>'}</div>`;}
function pairControls(p){if(p.status==='consents')return `<p>Наставник: ${p.consents.mentor?'согласен':'ожидается согласие'} · Наставляемый: ${p.consents.mentee?'согласен':'ожидается согласие'}</p>${['mentor','mentee'].includes(role)?`<div class="actions">${btn('pair-consent',p.id,'Согласиться на пару')}</div>${detail('Отказаться',form('pair-decline',textarea('reason','Причина отказа'),p.id,'Отказаться'))}`:''}${role==='director'?form('pair-present',`<div class="wide">${check('noConflict','Проверено отсутствие конфликта интересов')}</div>`+textarea('exceptionReason','Обоснование увеличения нагрузки','',false)+`<div class="wide">${check('exceptionDirector','Директор согласовал превышение лимита')}${check('exceptionMentor','Получено согласие наставника на увеличенную нагрузку')}</div>`,p.id,'Представить на назначение'):''}`;
if(p.status==='presented')return role==='rector'?form('pair-appoint',input('number','Номер распоряжения проректора')+input('date','Дата назначения','date')+input('end','Конец периода','date'),p.id,'Зарегистрировать распоряжение'):'<p class="hint">Ожидается оформление распоряжения проректора по академической работе.</p>';
return p.appointment?`<p class="hint">Распоряжение № ${esc(p.appointment.number)} от ${date(p.appointment.date)} · Период до ${date(p.appointment.end)}<br>План подготовить до ${date(p.planDeadline)} (10 дней пн–пт, без учета праздников).</p><div class="actions"><button data-pair="${p.id}">Открыть план и работу пары →</button></div>`:`<p class="hint">${esc(p.reason||'Программа завершена без назначения.')}</p>`;}
function pairsPage(){return `<span class="eyebrow">Маршрут наставничества</span><h1>Пары и индивидуальные планы</h1><p class="lead">Согласия → представление директора → распоряжение → совместный план → работа и оценка.</p><div class="stack" style="margin-top:28px">${state.pairs.map(p=>{const m=state.mentors.find(m=>m.id===p.mentorId),r=state.requests.find(r=>r.id===p.requestId);return `<article class="panel"><span class="step">${statuses[p.status]}</span><h3>${esc(m.name)} → ${esc(r.name)}</h3><p class="hint">${esc(r.goal)}</p>${pairControls(p)}</article>`;}).join('')||'<div class="empty">Пары появятся после подбора Школой. Начните с запроса и роли директора.</div>'}</div>`;}
const criteria=['Логичность структуры занятия','Связь этапов занятия','Управление временем','Достижение целей этапов','Активные и интерактивные методы','Цифровые инструменты','Дифференциация и потребности','Методы и результаты обучения','Активность обучающихся','Взаимодействие преподавателя и студентов','Взаимодействие студентов','Участие большинства','Формирующее оценивание','Обратная связь преподавателя','Рефлексия студентов'];
function planPage(){const p=state.pairs.find(p=>p.id===pairId);if(!p)return pairsPage();const r=state.requests.find(r=>r.id===p.requestId);const participant=['mentor','mentee'].includes(role);const editable=['planning','active'].includes(p.status);return `<span class="eyebrow">${esc(statuses[p.status])}</span><h1>Индивидуальный план</h1><p class="lead">${esc(r.name)} · ${esc(r.goal)}</p><p class="hint">Версия ${p.plan.version} · Срок подготовки: ${date(p.planDeadline)} · Период: ${date(p.appointment.date)} — ${date(p.appointment.end)}</p><section class="panel"><h2>Цели и организация</h2><p>${esc(p.plan.goal||'Цель еще не определена')}</p><p class="hint">${esc(p.plan.format||'')} · ${esc(p.plan.frequency||'')} · Рекомендуется встречаться не реже одного раза в две недели.</p>${participant&&editable?detail('Разработать или изменить план',form('plan-save',textarea('goal','Цель плана',p.plan.goal||r.goal)+input('frequency','Периодичность встреч','text',p.plan.frequency||'Один раз в две недели')+select('format','Формат встреч',formats,p.plan.format),p.id,'Сохранить новую версию')):''}<h3>Мероприятия и задачи</h3>${p.plan.items.map(i=>`<div class="item"><strong>${i.done?'✓ ':''}${esc(i.task)}</strong><p class="hint">До ${date(i.due)} · Поддержка: ${esc(i.support)}</p><p>Ожидаемый результат: ${esc(i.expected)}</p><p class="hint">Фиксация прогресса: ${esc(i.evidence)}</p>${i.result?`<p>Достигнуто: ${esc(i.result)}</p>`:''}${participant&&p.status==='active'&&!i.done?detail('Зафиксировать результат',form('item-complete',hidden('itemId',i.id)+textarea('result','Достигнутый результат'),p.id,'Завершить задачу')):''}</div>`).join('')||'<p class="hint">Добавьте хотя бы одну задачу с результатом и сроком.</p>'}${participant&&editable?detail('Добавить мероприятие в план',form('plan-item',textarea('task','Задача')+input('due','Срок','date')+textarea('support','Форма поддержки наставника')+textarea('expected','Ожидаемый результат')+textarea('evidence','Способ фиксации прогресса'),p.id,'Добавить задачу')):''}<p class="hint">Согласование версии: наставник ${p.plan.consents.mentor?'✓':'—'}, наставляемый ${p.plan.consents.mentee?'✓':'—'} · ${p.plan.approved?'Утвержден директором':'Ожидает утверждения'}</p><div class="actions">${participant&&p.status==='planning'?btn('plan-consent',p.id,'Согласовать эту версию'):''}${role==='director'&&p.status==='planning'?btn('plan-approve',p.id,'Утвердить план')+detail('Вернуть на доработку',form('plan-return',textarea('reason','Комментарий возврата'),p.id,'Вернуть план')):''}</div>${(p.plan.returns||[]).map(r=>`<p class="note">Возврат версии ${esc(r.version)}: ${esc(r.reason)}</p>`).join('')}${p.planHistory?.length?detail('История утвержденных версий',p.planHistory.map(v=>`<div class="item">Версия ${v.version}: ${esc(v.goal)} · ${v.items.length} задач</div>`).join('')):''}</section>
${p.status==='active'&&participant?`<section class="panel" style="margin-top:20px"><h2>Встречи и прогресс</h2>${detail('Зафиксировать встречу',form('meeting-add',input('date','Дата встречи','date')+select('format','Формат',formats)+textarea('result','Обобщенный результат для плана'),p.id))}${p.meetings.map(m=>`<div class="item">${date(m.date)} · ${esc(m.format)}<p>${esc(m.result)}</p><p class="hint">${m.confirmedBy?'Подтверждена вторым участником':m.author?'Ожидается подтверждение второго участника':'Старая запись без сведений об авторе'}</p>${m.author&&m.author!==role&&!m.confirmedBy?form('meeting-confirm',hidden('meetingId',m.id),p.id,'Подтвердить встречу'):''}</div>`).join('')||'<p class="hint">Встречи еще не зафиксированы.</p>'}</section><section class="panel private" style="margin-top:20px"><h2>Development Visit</h2><p class="hint">Частные наблюдения пары. Записывайте факты без вмешательства в занятие. Рекомендуется 2–3 фокуса.</p>${detail('1. Подготовить визит',form('visit-prepare',textarea('purpose','Цель визита')+input('course','Дисциплина')+input('topic','Тема занятия')+input('date','Дата','date')+input('time','Время','time')+input('location','Место')+select('lessonType','Тип занятия',['Лекция','Практическое','Лабораторное','Семинар','Другое'].map(x=>[x,x]))+textarea('objectives','Цели занятия')+textarea('outcomes','Планируемые результаты обучения')+input('students','Количество обучающихся','number')+textarea('group','Особенности группы и оснащение')+textarea('focus','Фокус наблюдения')+`<div class="wide">${check('criteriaShared','Наставляемый ознакомлен с критериями карты наблюдения')}</div>`,p.id,'Подготовить визит'))}${p.visits.map(v=>visitCard(p,v)).join('')}</section><section class="panel private" style="margin-top:20px"><h2>Оценка развития</h2><p class="hint">В начале — ожидания и цели; в середине — обратная связь; в конце — самооценка и отзыв.</p>${form('evaluation-save',select('stage','Этап',[['start','Начало'],['middle','Середина'],['final','Итог']])+textarea('text',role==='mentor'?'Краткий отзыв наставника':'Самооценка наставляемого'),p.id)}${Object.entries(p.evaluations).map(([stage,value])=>`<div class="item"><strong>${{start:'Начало',middle:'Середина',final:'Итог'}[stage]}</strong>${Object.entries(value).map(([who,text])=>`<p>${names[who]}: ${esc(text)}</p>`).join('')}</div>`).join('')}</section>`:''}
${role==='director'&&p.status==='active'?`<section class="panel" style="margin-top:20px"><h2>Завершение программы</h2><p class="hint">Итоговая самооценка: ${p.evaluations.final?.mentee?'получена':'ожидается'} · Отзыв наставника: ${p.evaluations.final?.mentor?'получен':'ожидается'}</p>${btn('pair-complete',p.id,'Завершить программу')}</section>`:''}
<section class="panel" style="margin-top:20px"><h2>Обращения участников</h2><p class="hint">Замена или досрочное завершение не рассматриваются как профессиональный неуспех.</p>${participant&&!['completed','ended'].includes(p.status)?detail('Подать обращение',form('change-request',select('type','Тип',[['replacement','Замена наставника'],['ending','Досрочное завершение']])+textarea('reason','Причина обращения'),p.id,'Отправить в Школу')):''}${p.changeRequests.map(c=>`<div class="item">${c.type==='replacement'?'Замена':'Досрочное завершение'} · ${esc(c.status)}<p>${esc(c.reason)}</p>${c.decision?`<p>Решение: ${esc(c.decision)}</p>`:''}${role==='director'&&c.status==='pending'?form('change-resolve',hidden('changeId',c.id)+textarea('reason','Решение Школы')+`<div class="wide">${check('end','Прекратить текущую пару и вернуть запрос на подбор')}</div>`,p.id,'Зафиксировать решение'):''}</div>`).join('')||'<p class="hint">Обращений нет.</p>'}</section>`;}
function visitCard(p,v){return `<article class="item"><h3>${esc(v.topic)} · ${date(v.date)}</h3><p>${esc(v.course)} · ${esc(v.lessonType)} · ${esc(v.location)} · ${esc(v.time)}</p><p>Цель: ${esc(v.purpose)}<br>Фокус: ${esc(v.focus)}</p><p class="hint">Контекст: ${esc(v.objectives)} · ${esc(v.outcomes)} · ${esc(v.group)} · ${esc(v.students)} обучающихся</p>${v.observations.map(o=>`<div class="item"><strong>${esc(o.timestamp)} · ${esc(o.criterion)}</strong><p>Преподаватель: ${esc(o.teacherAction)}</p><p>Обучающиеся: ${esc(o.studentAction)}</p><p class="hint">${esc(o.comment)}</p></div>`).join('')}${role==='mentor'&&v.status!=='complete'?detail('2. Добавить наблюдение',form('visit-observe',hidden('visitId',v.id)+input('timestamp','Таймкод, мм:сс')+select('criterion','Критерий',criteria.map(x=>[x,x]))+textarea('teacherAction','Наблюдаемое действие преподавателя')+textarea('studentAction','Действия обучающихся')+textarea('comment','Комментарии и вопросы','',false),p.id,'Добавить факт')):''}${v.status!=='complete'?detail('3. Зафиксировать совместное обсуждение',form('visit-reflect',hidden('visitId',v.id)+textarea('selfAnalysis','Краткий самоанализ наставляемого')+textarea('plus','Сильные стороны занятия')+textarea('question','Вопрос для профессионального обсуждения')+textarea('recommendation','Рекомендация наставника')+textarea('change','Изменения плана следующего занятия')+textarea('measurement','Как измерить эффект изменения')+textarea('observerReflection','Итоговая рефлексия наблюдателя')+`<div class="wide">${check('shared','Карта обсуждена с наставляемым')}</div>`,p.id,'Завершить обсуждение')):`<p class="tag">Визит завершен</p>${Object.entries({selfAnalysis:'Самоанализ',plus:'Плюс',question:'Вопрос',recommendation:'Рекомендация',change:'Следующий шаг',measurement:'Измерение',observerReflection:'Рефлексия наблюдателя'}).map(([k,t])=>`<p><strong>${t}:</strong> ${esc(v.reflection[k])}</p>`).join('')}`}</article>`;}
function reportPage(){const s=summary(state);return `<span class="eyebrow">Обзор программы</span><h1>Обобщенные показатели</h1><p class="lead">Руководство видит ход программы. Тексты частных наблюдений и рефлексии здесь не отображаются.</p><div class="stats" style="margin-top:28px">${Object.entries({Наставники:s.published,Запросы:s.requests,'Активные программы':s.active,Завершенные:s.completed}).map(([label,n])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><div class="panel"><h2>Границы демонстрации</h2><p>Все записи синтетические и хранятся в одном браузере. Переключатель ролей позволяет проверить сценарии. Серверная авторизация и многопользовательская работа требуют следующего этапа.</p><p class="hint">Часы наставничества: по положению 15 часов за одного наставляемого в триместр; здесь учет не заменяет индивидуальный план работы преподавателя.</p></div>`;}
function render(){app.innerHTML=`<header><div class="topbar"><div class="brand"><span class="brandmark">AITU</span>Наставничество</div><div class="actions"><button data-page="mentor-form">Подать как наставник</button><button class="primary" data-page="mentee-form">Подать как наставляемый</button></div></div><nav aria-label="Основная навигация">${[['dashboard','Главная'],['mentors','Наставники'],['requests','Заявки'],['pairs','Пары и планы'],['report','Обзор программы']].map(([p,t])=>`<button data-page="${p}" class="${page===p||(p==='pairs'&&page==='plan')?'selected':''}">${t}</button>`).join('')}</nav></header><main><div class="demo"><span>Локальный прототип · синтетические данные · без серверной авторизации</span><label>Роль сценария <select id="role">${Object.entries(names).map(([r,n])=>`<option value="${r}" ${role===r?'selected':''}>${n}</option>`).join('')}</select></label></div>${storageWarning?`<div class="note">${esc(storageWarning)}</div>`:''}${({dashboard,mentors:mentorCards,'mentor-form':mentorForm,'mentee-form':menteeForm,requests:requestsPage,pairs:pairsPage,plan:planPage,report:reportPage}[page]||dashboard)()}<footer>AITU · Дипломный проект · Наставничество как поддержка профессионального развития</footer></main>`;}
app.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;render();}});
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const at=e.target.selectionStart;render();const field=document.querySelector('#search');field.focus();field.setSelectionRange(at,at);}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.page){page=b.dataset.page;if(['mentor-form','mentee-form'].includes(page))role='teacher';render();window.scrollTo(0,0);return;}
  if('skill' in b.dataset){chosenSkill=b.dataset.skill;render();return;}
  if(b.dataset.area){area=b.dataset.area;render();return;}
  if(b.dataset.mentor){page='mentee-form';role='teacher';render();document.querySelector('[name=mentorId]').value=b.dataset.mentor;window.scrollTo(0,0);return;}
  if(b.dataset.pair){pairId=b.dataset.pair;page='plan';render();window.scrollTo(0,0);return;}
  if(b.dataset.action){try{persist(transition(state,b.dataset.action,{id:b.dataset.id},role));render();notify('Изменения сохранены.');}catch(err){notify(err.message,true);}}
});
app.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.dataset.action)return;const fd=new FormData(f);const d=Object.fromEntries(fd);d.skills=fd.getAll('skills');for(const c of f.querySelectorAll('input[type=checkbox]'))if(c.name!=='skills')d[c.name]=c.checked;
  try{persist(transition(state,f.dataset.action,d,role));if(['mentor-submit','request-submit'].includes(f.dataset.action))page='requests';render();notify('Сохранено. Следующий этап доступен в соответствующей роли.');}catch(err){notify(err.message,true);}
});
render();
